package com.autosphere.model;
import jakarta.persistence.*;
@Entity @Table(name="vehicles") public class Vehicle {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(nullable=false,unique=true) public String stockId;@Column(nullable=false) public String type;@Column(nullable=false) public String model;public String variant;public String fuel;public int year;public long kilometres;@Column(nullable=false) public long exShowroomPrice;public String status="AVAILABLE";public int owners=1;public String registrationMasked="UP-**-****";@Column(length=3000) public String inspectionReport="Inspection report pending admin upload.";@Column(length=1000) public String colours="White, Silver, Black";public java.time.LocalDate priceValidUntil=java.time.LocalDate.now().plusDays(15);@Column(length=500) public String priceChangeNote="Indicative price; confirm with showroom before purchase.";@Column(length=1000) public String imageUrl;@Column(length=2000) public String description;public Vehicle(){} }
